11	// AddSymbol registers a tradable symbol. It returns the created symbol.
12	func (e *Engine) AddSymbol(name string, priceScale int64) (*Symbol, error) {
13		if err := validateSymbolName(name); err != nil {
14			return nil, err
15		}
16		if priceScale < 0 || priceScale > 8 {
17			return nil, Invalidf("price_scale must be an integer between 0 and 8")
18		}
19		if _, exists := e.state.Symbols[name]; exists {
20			return nil, Conflictf("symbol %s already exists", name)
21		}
22		if _, err := e.emit(EventSymbolAdded, map[string]any{
23			"symbol":      name,
24			"price_scale": priceScale,
25		}); err != nil {
26			return nil, err
27		}
28		return e.state.Symbols[name], nil
29	}
30	
31	// PlaceOrder validates and matches an order. limitPrice is ignored for market
32	// orders. explicitID may be empty, in which case a sequence-derived id is used.
33	func (e *Engine) PlaceOrder(explicitID, symbol, side, orderType string, quantity, limitPrice int64) (OrderView, error) {
34		bookSymbol, ok := e.state.Symbols[symbol]
35		if !ok {
36			return OrderView{}, NotFoundf("symbol %s was not found", symbol)
37		}
38		if side != SideBuy && side != SideSell {
39			return OrderView{}, Invalidf("side must be buy or sell")
40		}
41		if orderType != TypeLimit && orderType != TypeMarket {
42			return OrderView{}, Invalidf("type must be limit or market")
43		}
44		if quantity <= 0 {
45			return OrderView{}, Invalidf("quantity must be a positive integer")
46		}
47		if quantity > MaxQuantity {
48			return OrderView{}, Invalidf("quantity must not exceed %d", MaxQuantity)
49		}
50		if orderType == TypeLimit {
51			if limitPrice <= 0 {
52				return OrderView{}, Invalidf("limit_price must be a positive integer for a limit order")
53			}
54			if limitPrice > MaxQuantity {
55				return OrderView{}, Invalidf("limit_price must not exceed %d ticks", MaxQuantity)
56			}
57		} else if limitPrice != 0 {
58			return OrderView{}, Invalidf("limit_price must be omitted for a market order")
59		}
60		id := explicitID
61		if id == "" {
62			id = fmt.Sprintf("ord-%d", len(e.state.Events)+1)
63		}
64		if err := validateIdentifier(id, "id"); err != nil {
65			return OrderView{}, err
66		}
67		if _, exists := e.state.Orders[id]; exists {
68			return OrderView{}, Conflictf("order %s already exists", id)
69		}
70		data := map[string]any{
71			"order_id": id,
72			"symbol":   symbol,
73			"side":     side,
74			"type":     orderType,
75			"quantity": quantity,
76		}
77		if orderType == TypeLimit {
78			data["limit_price"] = limitPrice
79		}
80		if _, err := e.emit(EventOrderAccepted, data); err != nil {
81			return OrderView{}, err
82		}
83		order := e.state.Orders[id]
84		e.match(order)
85		return orderView(order, bookSymbol, "created"), nil
86	}
87	
88	// CancelOrder cancels a live order. Terminal orders are a conflict.
89	func (e *Engine) CancelOrder(id string) (OrderView, error) {
90		order, ok := e.state.Orders[id]
91		if !ok {
92			return OrderView{}, NotFoundf("order %s was not found", id)
93		}
94		if order.Status != StatusOpen {
95			return OrderView{}, Conflictf("order %s is %s and can no longer be cancelled", id, order.Status)
96		}
97		if _, err := e.emit(EventOrderCancelled, map[string]any{
98			"order_id":        id,
99			"filled_quantity": order.Filled,
100		}); err != nil {
101			return OrderView{}, err
102		}
103		return orderView(e.state.Orders[id], e.state.Symbols[order.Symbol], "cancelled"), nil
104	}
105	
106	// GetOrder returns the public projection of one order.
107	func (e *Engine) GetOrder(id string) (OrderView, error) {
108		order, ok := e.state.Orders[id]
109		if !ok {
110			return OrderView{}, NotFoundf("order %s was not found", id)
111		}
112		return orderView(order, e.state.Symbols[order.Symbol], "updated"), nil
113	}
114	
115	// BookView is the public order book snapshot.
116	type BookView struct {
117		Symbol     string  `json:"symbol"`
118		PriceScale int     `json:"price_scale"`
119		Sequence   int64   `json:"sequence"`
120		Depth      int     `json:"depth"`
121		BestBid    *string `json:"best_bid"`
122		BestAsk    *string `json:"best_ask"`
123		LastTrade  *string `json:"last_trade_price"`
124		BidCount   int     `json:"bid_level_count"`
125		AskCount   int     `json:"ask_level_count"`
126		OpenOrders int     `json:"open_order_count"`
127		Crossed    bool    `json:"crossed"`
128		Bids       []Level `json:"bids"`
129		Asks       []Level `json:"asks"`
130	}
131	
132	// Book returns a depth-limited snapshot for one symbol.
133	func (e *Engine) Book(symbol string, depth int) (BookView, error) {
134		bookSymbol, ok := e.state.Symbols[symbol]
135		if !ok {
136			return BookView{}, NotFoundf("symbol %s was not found", symbol)
137		}
138		if depth <= 0 || depth > 100 {
139			return BookView{}, Invalidf("depth must be an integer between 1 and 100")
140		}
141		book, ok := e.state.Books[symbol]
142		if !ok {
143			return BookView{}, NotFoundf("symbol %s has no book", symbol)
144		}
145		bids, asks := book.Snapshot(depth)
146		view := BookView{
147			Symbol:     symbol,
148			PriceScale: bookSymbol.PriceScale,
149			Sequence:   int64(len(e.state.Events)),
150			Depth:      depth,
151			BidCount:   len(book.Bids),
152			AskCount:   len(book.Asks),
153			OpenOrders: len(book.Index),
154			Crossed:    bookCrossed(book),
155			Bids:       levelViews(bids),
156			Asks:       levelViews(asks),
157		}
158		if bid := book.bestBid(); bid != nil {
159			price := ScalePrice(bid.Price, bookSymbol.PriceScale)
160			view.BestBid = &price
161		}
162		if ask := book.bestAsk(); ask != nil {
163			price := ScalePrice(ask.Price, bookSymbol.PriceScale)
164			view.BestAsk = &price
165		}
166		for i := len(e.state.Trades) - 1; i >= 0; i-- {
167			if e.state.Trades[i].Symbol == symbol {
168				price := ScalePrice(e.state.Trades[i].Price, bookSymbol.PriceScale)
169				view.LastTrade = &price
170				break
171			}
172		}
173		return view, nil
174	}
175	
176	// TradePage is one page of the trade tape.
177	type TradePage struct {
178		Symbol     string      `json:"symbol"`
179		PriceScale int         `json:"price_scale"`
180		Total      int         `json:"total"`
181		Offset     int         `json:"offset"`
182		Limit      int         `json:"limit"`
183		Trades     []TradeView `json:"trades"`
184	}
185	
186	// Trades returns the executions of one symbol in sequence order.
187	func (e *Engine) Trades(symbol string, offset, limit int) (TradePage, error) {
188		bookSymbol, ok := e.state.Symbols[symbol]
189		if !ok {
190			return TradePage{}, NotFoundf("symbol %s was not found", symbol)
191		}
192		if offset < 0 {
193			return TradePage{}, Invalidf("offset must not be negative")
194		}
195		if limit <= 0 || limit > 1000 {
196			return TradePage{}, Invalidf("limit must be an integer between 1 and 1000")
197		}
198		all := []TradeView{}
199		for i := range e.state.Trades {
200			if e.state.Trades[i].Symbol != symbol {
201				continue
202			}
203			all = append(all, tradeView(&e.state.Trades[i], bookSymbol))
204		}
205		page := TradePage{
206			Symbol:     symbol,
207			PriceScale: bookSymbol.PriceScale,
208			Total:      len(all),
209			Offset:     offset,
210			Limit:      limit,
211			Trades:     []TradeView{},
212		}
213		if offset >= len(all) {
214			return page, nil
215		}
216		end := offset + limit
217		if end > len(all) {
218			end = len(all)
219		}
220		page.Trades = all[offset:end]
221		return page, nil
222	}
223	
224	// Symbols returns registered symbols in the order they were added.
225	func (e *Engine) Symbols() []Symbol {
226		names := make([]string, 0, len(e.state.Symbols))
227		for name := range e.state.Symbols {
228			names = append(names, name)
229		}
230		sort.Strings(names)
231		out := make([]Symbol, 0, len(names))
232		for _, name := range names {
233			out = append(out, *e.state.Symbols[name])
234		}
235		return out
236	}
237	
238	// Events returns a copy of the recorded event log.
239	func (e *Engine) Events() []Event {
240		return append([]Event{}, e.state.Events...)
241	}
242	
243	// Rebuild replays the event log from the very beginning and returns the state
244	// it produces. It reads no live structure and no clock, so the result depends
245	// only on the bytes of the log.
246	func (e *Engine) Rebuild() (*State, error) {
247		return rebuildFromFile(e.path)
248	}
249	
250	// ValidateIdempotencyKey normalises an optional Idempotency-Key header value.
251	func ValidateIdempotencyKey(key string) (string, error) {
252		trimmed := strings.TrimSpace(key)
253		if trimmed == "" {
254			return "", nil
255		}
256		if len(trimmed) > 200 {
257			return "", Invalidf("Idempotency-Key must be at most 200 characters")
258		}
259		return trimmed, nil
260	}
261	
262	// Remember returns the response stored for an idempotency key, or stores the
263	// response produced by action when the key is new.
264	func Remember[T any](e *Engine, key, operation string, action func() (T, error)) (T, error) {
265		var zero T
266		if key == "" {
267			return action()
268		}
269		if existing, ok := e.keys[key]; ok {
270			if existing.Operation != operation {
271				return zero, Conflictf("idempotency key was already used for another operation")
272			}
273			var cached T
274			if err := json.Unmarshal(existing.Response, &cached); err != nil {
275				return zero, err
276			}
277			return cached, nil
278		}
279		response, err := action()
280		if err != nil {
281			return zero, err
282		}
283		encoded, err := json.Marshal(response)
284		if err != nil {
285			return zero, err
286		}
287		e.keys[key] = idempotent{Operation: operation, Response: encoded}
288		if err := e.saveLedger(); err != nil {
289			return zero, err
290		}
291		return response, nil
292	}
293	
294	// saveLedger rewrites the ledger file with sorted keys so the file contents are
295	// stable across restarts. The ledger is a convenience cache: losing it only
296	// costs a replayed duplicate request, never engine state.
297	func (e *Engine) saveLedger() error {
298		if e.ledgerPath == "" {
299			return nil
300		}
301		document, err := json.Marshal(e.keys)
302		if err != nil {
303			return err
304		}
305		return os.WriteFile(e.ledgerPath, document, 0o644)
306	}
307	
308	// emit stamps an event with the injected clock and the next sequence number,
309	// appends it to the log, and applies it to the live state.
310	func (e *Engine) emit(eventType string, data map[string]any) (Event, error) {
311		event := Event{
312			Sequence: int64(len(e.state.Events) + 1),
313			At:       e.clock(),
314			Type:     eventType,
315			Data:     data,
316		}
317		line, err := json.Marshal(logEntry{
318			Sequence: event.Sequence,
319			At:       event.At,
320			Type:     event.Type,
321			Data:     event.Data,
322		})
323		if err != nil {
324			return Event{}, err
325		}
326		line = append(line, '\n')
327		if e.file != nil {
328			if _, err := e.file.Write(line); err != nil {
329				return Event{}, err
330			}
331			if err := e.file.Sync(); err != nil {
332				return Event{}, err
333			}
334		}
335		if err := e.state.Apply(rawEvent{At: event.At, Type: event.Type, Data: event.Data}); err != nil {
336			return Event{}, err
337		}
338		e.state.Events = append(e.state.Events, event)
339		return event, nil
340	}
341	
342	// match executes an incoming order against the opposite side of the book using
343	// price-time priority. Limit orders that cannot be filled immediately rest;
344	// market orders that cannot be filled completely are rejected.
345	func (e *Engine) match(taker *Order) {
346		book := e.state.Books[taker.Symbol]
347		if book == nil {
348			return
349		}
350		for taker.Remaining > 0 {
351			levels := &book.Asks
352			if taker.Side == SideSell {
353				levels = &book.Bids
354			}
355			if len(*levels) == 0 {
356				break
357			}
358			level := (*levels)[0]
359			if taker.Type == TypeLimit {
360				if taker.Side == SideBuy && level.Price > taker.LimitPrice {
361					break
362				}
363				if taker.Side == SideSell && level.Price < taker.LimitPrice {
364					break
365				}
366			}
367			maker := level.Orders[0]
368			quantity := taker.Remaining
369			if maker.Remaining < quantity {
370				quantity = maker.Remaining
371			}
372			if quantity <= 0 {
373				// Defensive: a level holding an empty order would otherwise loop.
374				book.clearLevel(level.Price, maker.Side)
375				continue
376			}
377			if err := e.execute(taker, maker, level.Price, quantity); err != nil {
378				return
379			}
380		}
381		if taker.Remaining == 0 {
382			return
383		}
384		if taker.Type == TypeLimit {
385			// Drop any stale level entry first: an order that partially traded has
386			// already been touched by Apply and must rest exactly once.
387			book.remove(taker)
388			book.add(taker)
389			return
390		}
391		// A market order never rests: any unexecuted remainder is rejected outright.
392		if _, err := e.emit(EventOrderRejected, map[string]any{
393			"order_id":           taker.ID,
394			"reason":             "insufficient_liquidity",
395			"unfilled_quantity":  taker.Remaining,
396			"filled_quantity":    taker.Filled,
397			"requested_quantity": taker.Quantity,
398		}); err != nil {
399			return
400		}
401	}
402	
403	// execute records one fill between a resting maker and an incoming taker.
404	//
405	// The quantities are computed from the state observed before the fill, then
406	// written as events and applied by State.Apply. The engine never mutates an
407	// order directly, so the live book and a book rebuilt from the log are the same
408	// data structure advanced by the same code.
409	func (e *Engine) execute(taker, maker *Order, price, quantity int64) error {
410		tradeID := fmt.Sprintf("trade-%d", len(e.state.Trades)+1)
411		if _, err := e.emit(EventTradeExecuted, map[string]any{
412			"trade_id":       tradeID,
413			"maker_order_id": maker.ID,
414			"taker_order_id": taker.ID,
415			"price":          price,
416			"quantity":       quantity,
417		}); err != nil {
418			return err
419		}
420		makerFilled := maker.Filled + quantity
421		makerRemaining := maker.Remaining - quantity
422		if err := e.emitOrderProgress(maker, makerFilled, makerRemaining, tradeID); err != nil {
423			return err
424		}
425		takerFilled := taker.Filled + quantity
426		takerRemaining := taker.Remaining - quantity
427		return e.emitOrderProgress(taker, takerFilled, takerRemaining, tradeID)
428	}
429	
430	// emitOrderProgress records a fill or, when the order is exhausted, its
431	// terminal filled state.
432	func (e *Engine) emitOrderProgress(order *Order, filled, remaining int64, tradeID string) error {
433		if remaining > 0 {
434			_, err := e.emit(EventOrderUpdated, map[string]any{
435				"order_id":           order.ID,
436				"filled_quantity":    filled,
437				"remaining_quantity": remaining,
438				"trade_id":           tradeID,
439			})
440			return err
441		}
442		_, err := e.emit(EventOrderFilled, map[string]any{
443			"order_id":        order.ID,
444			"filled_quantity": filled,
445			"trade_id":        tradeID,
446		})
447		return err
448	}
449	
450	// bookCrossed reports whether the best bid is at or above the best ask, which
451	// the engine treats as an invariant violation.
452	func bookCrossed(book *Book) bool {
453		return BookCrossed(book)
454	}
455	
456	// BookCrossed reports whether a book's best bid is at or above its best ask.
457	// A well formed book never is: it would mean an executable pair was left
458	// unmatched.
459	func BookCrossed(book *Book) bool {
460		bid, ask := book.bestBid(), book.bestAsk()
461		if bid == nil || ask == nil {
462			return false
463		}
464		return bid.Price >= ask.Price
465	}
466	
467	// CountOpenOrders counts resting orders for one symbol.
468	func (e *Engine) CountOpenOrders(symbol string) int {
469		book, ok := e.state.Books[symbol]
470		if !ok {
471			return 0
472		}
473		return len(book.Index)
474	}
475	
476	// Close releases the event log file handle.
477	func (e *Engine) Close() error {
478		if e.file == nil {
479			return nil
480		}
481		err := e.file.Close()
482		e.file = nil
483		return err
484	}
485	
486	// OpenLedger loads the idempotency ledger from disk, if it exists.
487	func (e *Engine) OpenLedger(path string) error {
488		data, err := os.ReadFile(path)
489		if err != nil {
490			if os.IsNotExist(err) {
491				e.keys = map[string]idempotent{}
492				e.ledgerPath = path
493				return nil
494			}
495			return err
496		}
497		keys := map[string]idempotent{}
498		if len(data) > 0 {
499			if err := json.Unmarshal(data, &keys); err != nil {
500				return fmt.Errorf("idempotency ledger is not valid JSON: %w", err)
501			}
502		}
503		e.keys = keys
504		e.ledgerPath = path
505		return nil
506	}
