84	// Apply replays a single already-stamped event. It is used by Rebuild and by
85	// every live mutation, which funnels through the log so that live state and
86	// replayed state cannot drift apart.
87	func (s *State) Apply(event rawEvent) error {
88		switch event.Type {
89		case EventSymbolAdded:
90			name, err := stringField(event.Data, "symbol")
