123	func (s *State) applyOrderAccepted(event rawEvent) error {
124		id, err := stringField(event.Data, "order_id")
125		if err != nil {
126			return err
127		}
128		symbol, err := stringField(event.Data, "symbol")
129		if err != nil {
130			return err
131		}
