138			return err
139		}
140		quantity, err := intField(event.Data, "quantity")
141		if err != nil {
142			return err
143		}
144		if _, exists := s.Orders[id]; exists {
145			return fmt.Errorf("event log accepts order %s twice", id)
146		}
