154		order := &Order{
155			ID:         id,
156			Symbol:     symbol,
157			Side:       side,
158			Type:       orderType,
159			LimitPrice: price,
160			Quantity:   quantity,
161			Remaining:  quantity,
162			Status:     StatusOpen,
163			Trades:     []string{},
164			Sequence:   int64(len(s.Events) + 1),
165			CreatedAt:  event.At,
166			UpdatedAt:  event.At,
