174	// applyOrderUpdated and applyOrderFilled consume the quantities recorded in the
175	// event itself, never the live order, so replay reproduces exactly the values
176	// that were reported at the time of the fill.
177	func (s *State) applyOrderUpdated(event rawEvent) error {
178		id, err := stringField(event.Data, "order_id")
179		if err != nil {
180			return err
181		}
182		filled, err := intField(event.Data, "filled_quantity")
183		if err != nil {
184			return err
185		}
