200		order.UpdatedAt = event.At
201		if remaining == 0 {
202			s.book(order.Symbol).remove(order)
203		}
204		return nil
205	}
206	
207	func (s *State) applyOrderFilled(event rawEvent) error {
208		id, err := stringField(event.Data, "order_id")
209		if err != nil {
210			return err
211		}
212		filled, err := intField(event.Data, "filled_quantity")
213		if err != nil {
214			return err
215		}
216		order, ok := s.Orders[id]
217		if !ok {
218			return fmt.Errorf("event log fills unknown order %s", id)
219		}
220		order.Filled = filled
221		order.Remaining = 0
222		order.Status = StatusFilled
223		order.UpdatedAt = event.At
224		s.book(order.Symbol).remove(order)
225		return nil
226	}
227	
228	func (s *State) applyOrderCancelled(event rawEvent) error {
229		id, err := stringField(event.Data, "order_id")
230		if err != nil {
231			return err
232		}
233		filled, err := intField(event.Data, "filled_quantity")
234		if err != nil {
235			return err
236		}
237		order, ok := s.Orders[id]
238		if !ok {
239			return fmt.Errorf("event log cancels unknown order %s", id)
240		}
241		order.Filled = filled
242		if filled < order.Quantity {
243			order.Status = StatusCancelled
244		}
245		order.UpdatedAt = event.At
246		s.book(order.Symbol).remove(order)
247		return nil
248	}
249	
250	func (s *State) applyOrderRejected(event rawEvent) error {
251		id, err := stringField(event.Data, "order_id")
252		if err != nil {
253			return err
254		}
255		filled, err := intField(event.Data, "filled_quantity")
256		if err != nil {
257			return err
258		}
259		order, ok := s.Orders[id]
260		if !ok {
261			return fmt.Errorf("event log rejects unknown order %s", id)
262		}
263		order.Filled = filled
264		order.Status = StatusRejected
265		order.UpdatedAt = event.At
266		s.book(order.Symbol).remove(order)
267		return nil
268	}
269	
270	func (s *State) applyTradeExecuted(event rawEvent) error {
271		tradeID, err := stringField(event.Data, "trade_id")
272		if err != nil {
273			return err
274		}
275		makerID, err := stringField(event.Data, "maker_order_id")
276		if err != nil {
277			return err
278		}
279		takerID, err := stringField(event.Data, "taker_order_id")
280		if err != nil {
281			return err
282		}
283		price, err := intField(event.Data, "price")
284		if err != nil {
285			return err
286		}
287		quantity, err := intField(event.Data, "quantity")
288		if err != nil {
289			return err
290		}
291		maker, ok := s.Orders[makerID]
292		if !ok {
293			return fmt.Errorf("trade %s references unknown maker %s", tradeID, makerID)
294		}
295		taker, ok := s.Orders[takerID]
296		if !ok {
297			return fmt.Errorf("trade %s references unknown taker %s", tradeID, takerID)
298		}
299		s.Trades = append(s.Trades, Trade{
300			ID:         tradeID,
301			Sequence:   int64(len(s.Trades) + 1),
302			Symbol:     maker.Symbol,
303			Price:      price,
304			Quantity:   quantity,
305			MakerID:    makerID,
306			TakerID:    takerID,
307			MakerSide:  maker.Side,
308			ExecutedAt: event.At,
309		})
310		maker.Trades = append(maker.Trades, tradeID)
311		taker.Trades = append(taker.Trades, tradeID)
312		return nil
313	}
314	
315	func stringField(data map[string]any, name string) (string, error) {
316		value, ok := data[name]
317		if !ok {
318			return "", fmt.Errorf("event data is missing %s", name)
319		}
320		text, ok := value.(string)
321		if !ok {
322			return "", fmt.Errorf("event data field %s must be a string", name)
323		}
324		return text, nil
325	}
326	
327	// numericField extracts an integer from a decoded payload. Values that reached
328	// the engine through json.Unmarshal arrive as float64; values fed straight from
329	// the live code path keep their Go integer type.
330	func numericField(value any) (int64, bool) {
331		switch number := value.(type) {
332		case float64:
333			if number != float64(int64(number)) {
334				return 0, false
335			}
336			return int64(number), true
337		case int:
338			return int64(number), true
339		case int32:
340			return int64(number), true
341		case int64:
342			return number, true
343		case json.Number:
344			parsed, err := number.Int64()
345			if err != nil {
346				return 0, false
347			}
348			return parsed, true
349		default:
350			return 0, false
351		}
352	}
353	
354	func intField(data map[string]any, name string) (int64, error) {
355		value, ok := data[name]
356		if !ok {
357			return 0, fmt.Errorf("event data is missing %s", name)
358		}
359		number, ok := numericField(value)
360		if !ok {
361			return 0, fmt.Errorf("event data field %s must be an integer", name)
362		}
363		return number, nil
364	}
365	
366	func optionalIntField(data map[string]any, name string) (int64, error) {
367		value, ok := data[name]
368		if !ok || value == nil {
369			return 0, nil
370		}
371		number, ok := numericField(value)
372		if !ok {
373			return 0, fmt.Errorf("event data field %s must be an integer", name)
374		}
375		return number, nil
376	}
377	
378	// add appends an order to its price level, keeping price order and FIFO order
379	// within a level.
380	func (b *Book) add(order *Order) {
381		if order.Remaining <= 0 {
382			return
383		}
384		levels, ascending := &b.Asks, true
385		if order.Side == SideBuy {
386			levels, ascending = &b.Bids, false
387		}
388		for _, level := range *levels {
389			if level.Price == order.LimitPrice {
390				level.Orders = append(level.Orders, order)
391				b.Index[order.ID] = order
392				return
393			}
394		}
395		level := &LevelState{Price: order.LimitPrice, Orders: []*Order{order}}
396		*levels = append(*levels, level)
397		sortLevels(*levels, ascending)
398		b.Index[order.ID] = order
399	}
400	
401	func sortLevels(levels []*LevelState, ascending bool) {
402		sort.SliceStable(levels, func(i, j int) bool {
403			if ascending {
404				return levels[i].Price < levels[j].Price
405			}
406			return levels[i].Price > levels[j].Price
407		})
408	}
409	
410	// remove takes an order out of the book. Removing an order that is not resting
411	// is a no-op.
412	func (b *Book) remove(order *Order) {
413		delete(b.Index, order.ID)
414		levels := &b.Asks
415		if order.Side == SideBuy {
416			levels = &b.Bids
417		}
418		for i, level := range *levels {
419			if level.Price != order.LimitPrice {
420				continue
421			}
422			for j, resting := range level.Orders {
423				if resting.ID == order.ID {
424					level.Orders = append(level.Orders[:j], level.Orders[j+1:]...)
425					break
426				}
427			}
428			if len(level.Orders) == 0 {
429				*levels = append((*levels)[:i], (*levels)[i+1:]...)
430			}
431			return
432		}
433	}
434	
435	// clearLevel empties a whole price level.
436	func (b *Book) clearLevel(price int64, side string) {
437		levels := &b.Asks
438		if side == SideBuy {
439			levels = &b.Bids
440		}
441		for i, level := range *levels {
442			if level.Price != price {
443				continue
444			}
445			for _, order := range level.Orders {
446				delete(b.Index, order.ID)
447			}
448			*levels = append((*levels)[:i], (*levels)[i+1:]...)
449			return
450		}
451	}
452	
453	// bestAsk and bestBid return the top of book, or nil when that side is empty.
454	func (b *Book) bestAsk() *LevelState {
455		if len(b.Asks) == 0 {
456			return nil
457		}
458		return b.Asks[0]
459	}
460	
461	func (b *Book) bestBid() *LevelState {
462		if len(b.Bids) == 0 {
463			return nil
464		}
465		return b.Bids[0]
466	}
467	
468	// Snapshot returns up to depth levels of each side, best price first.
469	func (b *Book) Snapshot(depth int) ([]Level, []Level) {
470		build := func(levels []*LevelState) []Level {
471			out := []Level{}
472			for i, level := range levels {
473				if i >= depth {
474					break
475				}
476				quantity := int64(0)
477				for _, order := range level.Orders {
478					quantity += order.Remaining
479				}
480				out = append(out, Level{Price: level.Price, Quantity: quantity, OrderCount: len(level.Orders)})
481			}
482			return out
483		}
484		return build(b.Bids), build(b.Asks)
485	}
486	
487	// ledgerFileName stores the Idempotency-Key ledger next to the event log.
488	const ledgerFileName = "idempotency.json"
489	
490	// Engine is the live matching service: it owns the derived state, the
491	// append-only event log, and the idempotency ledger.
492	type Engine struct {
493		state *State
494		clock func() int64
495		file  *os.File
496		path  string
497	
498		keys       map[string]idempotent
499		ledgerPath string
500	}
501	
502	// idempotent remembers the response returned for an Idempotency-Key.
503	type idempotent struct {
504		Operation string          `json:"operation"`
505		Response  json.RawMessage `json:"response"`
506	}
507	
508	// NewEngine opens (and creates if needed) the event log inside dataDir.
509	func NewEngine(dataDir string, clock func() int64) (*Engine, error) {
510		if clock == nil {
511			return nil, fmt.Errorf("clock must not be nil")
512		}
513		if err := os.MkdirAll(dataDir, 0o755); err != nil {
514			return nil, err
515		}
516		engine := &Engine{
517			state:      NewState(),
518			clock:      clock,
519			path:       filepath.Join(dataDir, LogFileName),
520			keys:       map[string]idempotent{},
521			ledgerPath: filepath.Join(dataDir, ledgerFileName),
522		}
523		if _, err := os.Stat(engine.path); err == nil {
524			if err := engine.replayFile(); err != nil {
525				return nil, err
526			}
527		} else if !os.IsNotExist(err) {
528			return nil, err
529		}
530		file, err := os.OpenFile(engine.path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
531		if err != nil {
532			return nil, err
533		}
534		engine.file = file
535		if err := engine.OpenLedger(engine.ledgerPath); err != nil {
536			return nil, err
537		}
538		return engine, nil
539	}
540	
541	// replayFile rebuilds in-memory state from the on-disk event log.
542	func (e *Engine) replayFile() error {
543		state, err := rebuildFromFile(e.path)
544		if err != nil {
545			return err
546		}
547		e.state = state
548		return nil
549	}
550	
551	// rebuildFromFile replays the event log from the very beginning and returns the
552	// state it produces. It touches no live counter and reads no clock, so the
553	// result is a pure function of the log.
554	func rebuildFromFile(path string) (*State, error) {
555		file, err := os.Open(path)
556		if err != nil {
557			if os.IsNotExist(err) {
558				return NewState(), nil
559			}
560			return nil, err
561		}
562		defer file.Close()
563		state := NewState()
564		if err := scanLog(file, state); err != nil {
565			return nil, err
566		}
567		return state, nil
568	}
569	
570	// scanLog applies every line of an event log to state in order, rejecting gaps.
571	func scanLog(file *os.File, state *State) error {
572		scanner := bufio.NewScanner(file)
573		scanner.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
574		sequence := int64(0)
575		for scanner.Scan() {
576			line := scanner.Bytes()
577			if len(line) == 0 {
578				continue
579			}
580			var entry logEntry
581			if err := json.Unmarshal(line, &entry); err != nil {
582				return fmt.Errorf("event log line %d is not valid JSON: %w", sequence+1, err)
583			}
584			sequence++
585			if entry.Sequence != sequence {
586				return fmt.Errorf("event log is not contiguous at line %d", sequence)
587			}
588			raw := rawEvent{At: entry.At, Type: entry.Type, Data: entry.Data}
589			if err := state.Apply(raw); err != nil {
590				return fmt.Errorf("event log line %d: %w", sequence, err)
591			}
592			state.Events = append(state.Events, Event{
593				Sequence: entry.Sequence,
594				At:       entry.At,
595				Type:     entry.Type,
596				Data:     entry.Data,
597			})
598		}
599		return scanner.Err()
600	}
