1	// Package server exposes the Matchbook matching engine over HTTP.
2	package server
3	
4	import (
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"log"
10		"net"
11		"net/http"
12		"net/url"
13		"sort"
14		"strings"
15		"time"
16	
17		"matchbook/internal/engine"
18	)
19	
20	const maxBodyBytes = 1 << 20
21	
22	// API holds the engine behind the HTTP contract.
23	type API struct {
24		engine *engine.Engine
25	}
26	
27	// New returns an API over the given engine.
28	func New(matching *engine.Engine) *API {
29		return &API{engine: matching}
30	}
31	
32	// Handler returns the HTTP handler for the public contract.
33	func (a *API) Handler() http.Handler {
34		mux := http.NewServeMux()
35		mux.HandleFunc("/", a.route)
36		return mux
37	}
38	
39	// errorBody is the single error envelope used by every endpoint.
40	type errorBody struct {
41		Error errorDetail `json:"error"`
42	}
43	
44	type errorDetail struct {
45		Code    string `json:"code"`
46		Message string `json:"message"`
47	}
48	
49	type symbolRequest struct {
50		Symbol     *string `json:"symbol"`
51		PriceScale *int64  `json:"price_scale"`
52	}
53	
54	type orderRequest struct {
55		ID         *string  `json:"id"`
56		Symbol     *string  `json:"symbol"`
57		Side       *string  `json:"side"`
58		Type       *string  `json:"type"`
59		Quantity   *float64 `json:"quantity"`
60		LimitPrice *float64 `json:"limit_price"`
61	}
62	
63	type replayRequest struct {
64		Symbol *string `json:"symbol"`
65	}
66	
67	type consistency struct {
68		Consistent            bool   `json:"consistent"`
69		Symbol                string `json:"symbol"`
70		EventCount            int    `json:"event_count"`
71		BookMatched           bool   `json:"book_matched"`
72		OrdersMatched         bool   `json:"orders_matched"`
73		TradesMatched         bool   `json:"trades_matched"`
74		BidCount              int    `json:"bid_level_count"`
75		AskCount              int    `json:"ask_level_count"`
76		OpenOrderCount        int    `json:"open_order_count"`
77		RebuiltOpenOrderCount int    `json:"rebuilt_open_order_count"`
78		TradeCount            int    `json:"trade_count"`
79		RebuiltTradeCount     int    `json:"rebuilt_trade_count"`
80	}
81	
82	func (a *API) route(response http.ResponseWriter, request *http.Request) {
83		segments := splitPath(request.URL.Path)
84		if segments == nil {
85			a.writeError(response, invalidf("request path must not contain empty segments"))
86			return
87		}
88		switch {
89		case request.Method == http.MethodGet && len(segments) == 1 && segments[0] == "health":
90			a.writeJSON(response, http.StatusOK, map[string]any{"status": "ok"})
91		case request.Method == http.MethodPost && len(segments) == 1 && segments[0] == "symbols":
92			a.writeResult(response, a.createSymbol(request))
93		case request.Method == http.MethodGet && len(segments) == 1 && segments[0] == "symbols":
94			body := map[string]any{"symbols": a.engine.Symbols()}
95			a.writeJSON(response, http.StatusOK, body)
96		case request.Method == http.MethodPost && len(segments) == 1 && segments[0] == "orders":
97			a.writeResult(response, a.createOrder(request))
98		case len(segments) == 2 && segments[0] == "orders" && request.Method == http.MethodDelete:
99			a.writeResult(response, a.cancelOrder(request, segments[1]))
100		case len(segments) == 1 && segments[0] == "book" && request.Method == http.MethodGet:
101			a.writeResult(response, a.getBook(request))
102		case len(segments) == 1 && segments[0] == "trades" && request.Method == http.MethodGet:
103			a.writeResult(response, a.getTrades(request))
104		case len(segments) == 1 && segments[0] == "replay" && request.Method == http.MethodPost:
105			a.writeResult(response, a.replay(request))
106		default:
107			if isKnownPath(segments) {
108				response.Header().Set("Allow", allowedMethods(segments, request))
109				a.writeError(response, &apiError{
110					code:    "method_not_allowed",
111					message: fmt.Sprintf("%s is not allowed on this route", request.Method),
112					status:  http.StatusMethodNotAllowed,
113				})
114				return
115			}
116			a.writeError(response, notFoundf("route %s was not found", request.URL.Path))
117		}
118	}
119	
120	// isKnownPath reports whether a path exists regardless of the method used.
121	func isKnownPath(segments []string) bool {
122		if len(segments) == 0 {
123			return false
124		}
125		switch segments[0] {
126		case "health":
127			return len(segments) == 1
128		case "symbols", "book", "trades", "replay":
129			return len(segments) == 1
130		case "orders":
131			return len(segments) == 1 || len(segments) == 2
132		default:
133			return false
134		}
135	}
136	
137	func allowedMethods(segments []string, request *http.Request) string {
138		switch segments[0] {
139		case "health", "book", "trades":
140			return "GET"
141		case "symbols":
142			return "GET, POST"
143		case "orders":
144			if len(segments) == 2 {
145				return "DELETE"
146			}
147			return "POST"
148		case "replay":
149			return "POST"
150		default:
151			return "GET"
152		}
153	}
154	
155	// splitPath returns the path segments, an empty slice for "/", or nil when the
156	// path contains empty segments.
157	func splitPath(path string) []string {
158		if path == "" {
159			return nil
160		}
161		if path == "/" {
162			return []string{}
163		}
164		if strings.HasSuffix(path, "/") {
165			return nil
166		}
167		trimmed := strings.TrimPrefix(path, "/")
168		segments := strings.Split(trimmed, "/")
169		for _, segment := range segments {
170			if segment == "" {
171				return nil
172			}
173		}
174		decoded := make([]string, 0, len(segments))
175		for _, segment := range segments {
176			value, err := url.PathUnescape(segment)
177			if err != nil {
178				return nil
179			}
180			decoded = append(decoded, value)
181		}
182		return decoded
183	}
184	
185	func (a *API) createSymbol(request *http.Request) callResult {
186		raw, err := readBody(request)
187		if err != nil {
188			return callResult{err: err}
189		}
190		var document symbolRequest
191		if err := decodeDocument(raw, &document); err != nil {
192			return callResult{err: err}
193		}
194		if document.Symbol == nil || strings.TrimSpace(*document.Symbol) == "" {
195			return callResult{err: invalidf("symbol must be a non-empty string")}
196		}
197		if document.PriceScale == nil {
198			return callResult{err: invalidf("price_scale is required")}
199		}
200		scale, err := engine.AsInt64(*document.PriceScale, "price_scale")
201		if err != nil {
202			return callResult{err: err}
203		}
204		key, err := a.idempotencyKey(request)
205		if err != nil {
206			return callResult{err: err}
207		}
208		symbol := strings.TrimSpace(*document.Symbol)
209		created, err := engine.Remember(a.engine, key, "create-symbol:"+symbol, func() (*engine.Symbol, error) {
210			return a.engine.AddSymbol(symbol, scale)
211		})
212		if err != nil {
213			return callResult{err: err}
214		}
215		return callResult{status: http.StatusCreated, body: created}
216	}
217	
218	func (a *API) createOrder(request *http.Request) callResult {
219		raw, err := readBody(request)
220		if err != nil {
221			return callResult{err: err}
222		}
223		var document orderRequest
224		if err := decodeDocument(raw, &document); err != nil {
225			return callResult{err: err}
226		}
227		if document.Symbol == nil || strings.TrimSpace(*document.Symbol) == "" {
228			return callResult{err: invalidf("symbol must be a non-empty string")}
229		}
230		if document.Side == nil {
231			return callResult{err: invalidf("side is required")}
232		}
233		if document.Type == nil {
234			return callResult{err: invalidf("type is required")}
235		}
236		if document.Quantity == nil {
237			return callResult{err: invalidf("quantity is required")}
238		}
239		symbol := strings.TrimSpace(*document.Symbol)
240		side := strings.TrimSpace(*document.Side)
241		orderType := strings.TrimSpace(*document.Type)
242		if side != engine.SideBuy && side != engine.SideSell {
243			return callResult{err: invalidf("side must be buy or sell")}
244		}
245		if orderType != engine.TypeLimit && orderType != engine.TypeMarket {
246			return callResult{err: invalidf("type must be limit or market")}
247		}
248		quantity, err := engine.AsInt64(*document.Quantity, "quantity")
249		if err != nil {
250			return callResult{err: err}
251		}
252		var limitPrice int64
253		switch {
254		case document.LimitPrice == nil:
255			if orderType == engine.TypeLimit {
256				return callResult{err: invalidf("limit_price is required for a limit order")}
257			}
258		case orderType == engine.TypeMarket:
259			return callResult{err: invalidf("limit_price must be omitted for a market order")}
260		default:
261			parsed, err := engine.AsInt64(*document.LimitPrice, "limit_price")
262			if err != nil {
263				return callResult{err: err}
264			}
265			limitPrice = parsed
266		}
267		identifier := ""
268		if document.ID != nil {
269			identifier = strings.TrimSpace(*document.ID)
270		}
271		key, err := a.idempotencyKey(request)
272		if err != nil {
273			return callResult{err: err}
274		}
275		view, err := engine.Remember(a.engine, key, "place-order:"+symbol, func() (engine.OrderView, error) {
276			return a.engine.PlaceOrder(identifier, symbol, side, orderType, quantity, limitPrice)
277		})
278		if err != nil {
279			return callResult{err: err}
280		}
281		return callResult{status: http.StatusCreated, body: view}
282	}
283	
284	func (a *API) cancelOrder(request *http.Request, id string) callResult {
285		if _, err := readBody(request); err != nil {
286			return callResult{err: err}
287		}
288		key, err := a.idempotencyKey(request)
289		if err != nil {
290			return callResult{err: err}
291		}
292		view, err := engine.Remember(a.engine, key, "cancel-order:"+id, func() (engine.OrderView, error) {
293			return a.engine.CancelOrder(id)
294		})
295		if err != nil {
296			return callResult{err: err}
297		}
298		return callResult{status: http.StatusOK, body: view}
299	}
300	
301	func (a *API) getBook(request *http.Request) callResult {
302		query, err := queryValues(request.URL.RawQuery, []string{"symbol", "depth"})
303		if err != nil {
304			return callResult{err: err}
305		}
306		symbol := strings.TrimSpace(query.Get("symbol"))
307		if symbol == "" {
308			return callResult{err: invalidf("symbol query parameter is required")}
309		}
310		depth, err := engine.ParseDepth(query.Get("depth"))
311		if err != nil {
312			return callResult{err: err}
313		}
314		book, err := a.engine.Book(symbol, depth)
315		if err != nil {
316			return callResult{err: err}
317		}
318		return callResult{status: http.StatusOK, body: book}
319	}
320	
321	func (a *API) getTrades(request *http.Request) callResult {
322		query, err := queryValues(request.URL.RawQuery, []string{"symbol", "limit", "offset"})
323		if err != nil {
324			return callResult{err: err}
325		}
326		symbol := strings.TrimSpace(query.Get("symbol"))
327		if symbol == "" {
328			return callResult{err: invalidf("symbol query parameter is required")}
329		}
330		limit, offset, err := engine.ParsePage(query.Get("limit"), query.Get("offset"))
331		if err != nil {
332			return callResult{err: err}
333		}
334		page, err := a.engine.Trades(symbol, offset, limit)
335		if err != nil {
336			return callResult{err: err}
337		}
338		return callResult{status: http.StatusOK, body: page}
339	}
340	
341	// replay rebuilds every book from the event log and compares it with the live
342	// state field by field.
343	func (a *API) replay(request *http.Request) callResult {
344		raw, err := readBody(request)
345		if err != nil {
346			return callResult{err: err}
347		}
348		document := replayRequest{}
349		if len(raw) > 0 {
350			if err := decodeDocument(raw, &document); err != nil {
351				return callResult{err: err}
352			}
353		}
354		rebuilt, err := a.engine.Rebuild()
355		if err != nil {
356			return callResult{err: err}
357		}
358		live := a.engine.Events()
359		results := make([]consistency, 0)
360		symbols := map[string]bool{}
361		for _, symbol := range a.engine.Symbols() {
362			symbols[symbol.Name] = true
363		}
364		for name := range rebuilt.Symbols {
365			symbols[name] = true
366		}
367		names := make([]string, 0, len(symbols))
368		for name := range symbols {
369			names = append(names, name)
370		}
371		sort.Strings(names)
372		if document.Symbol != nil && !symbols[*document.Symbol] {
373			return callResult{err: notFoundf("symbol %s was not found", *document.Symbol)}
374		}
375		for _, name := range names {
376			if document.Symbol != nil && *document.Symbol != name {
377				continue
378			}
379			results = append(results, a.compareSymbol(name, rebuilt))
380		}
381		consistent := len(live) == len(rebuilt.Events)
382		for _, result := range results {
383			if !result.Consistent {
384				consistent = false
385			}
386		}
387		body := map[string]any{
388			"consistent":       consistent,
389			"live_sequence":    len(live),
390			"rebuilt_sequence": len(rebuilt.Events),
391			"symbol_count":     len(results),
392			"books":            results,
393		}
394		return callResult{status: http.StatusOK, body: body}
395	}
396	
397	func (a *API) compareSymbol(name string, rebuilt *engine.State) consistency {
398		result := consistency{Symbol: name, EventCount: len(rebuilt.Events)}
399		liveBook, liveErr := a.engine.Book(name, 100)
400		rebuiltBook, rebuiltErr := rebuildBookView(rebuilt, name)
401		result.BookMatched = liveErr == nil && rebuiltErr == nil && equalBook(liveBook, rebuiltBook)
402		result.BidCount = rebuiltBook.BidCount
403		result.AskCount = rebuiltBook.AskCount
404		result.OpenOrderCount = a.engine.CountOpenOrders(name)
405		result.RebuiltOpenOrderCount = rebuiltBook.OpenOrders
406		result.OrdersMatched = result.OpenOrderCount == result.RebuiltOpenOrderCount
407		liveTrades, liveTradeErr := a.engine.Trades(name, 0, 1000)
408		rebuiltTrades, rebuiltTradeErr := rebuiltTradePage(rebuilt, name)
409		if liveTradeErr == nil && rebuiltTradeErr == nil {
410			result.TradeCount = liveTrades.Total
411			result.RebuiltTradeCount = rebuiltTrades.Total
412			result.TradesMatched = result.TradeCount == result.RebuiltTradeCount
413		}
414		result.Consistent = result.BookMatched && result.OrdersMatched && result.TradesMatched
415		return result
416	}
417	
418	func equalBook(live engine.BookView, rebuilt engine.BookView) bool {
419		return live.Symbol == rebuilt.Symbol &&
420			live.PriceScale == rebuilt.PriceScale &&
421			live.Depth == rebuilt.Depth &&
422			equalStringPtr(live.BestBid, rebuilt.BestBid) &&
423			equalStringPtr(live.BestAsk, rebuilt.BestAsk) &&
424			equalStringPtr(live.LastTrade, rebuilt.LastTrade) &&
425			live.BidCount == rebuilt.BidCount &&
426			live.AskCount == rebuilt.AskCount &&
427			live.OpenOrders == rebuilt.OpenOrders &&
428			live.Crossed == rebuilt.Crossed &&
429			equalLevels(live.Bids, rebuilt.Bids) &&
430			equalLevels(live.Asks, rebuilt.Asks)
431	}
432	
433	func equalStringPtr(left, right *string) bool {
434		if left == nil || right == nil {
435			return left == nil && right == nil
436		}
437		return *left == *right
438	}
439	
440	func equalLevels(left, right []engine.Level) bool {
441		if len(left) != len(right) {
442			return false
443		}
444		for i := range left {
445			if left[i] != right[i] {
446				return false
447			}
448		}
449		return true
450	}
451	
452	// rebuildBookView derives a book snapshot from replayed state only. It must
453	// agree with engine.Book field for field, otherwise replay is not consistent.
454	func rebuildBookView(state *engine.State, symbol string) (engine.BookView, error) {
455		book := state.Books[symbol]
456		meta := state.Symbols[symbol]
457		if book == nil || meta == nil {
458			return engine.BookView{}, fmt.Errorf("rebuilt state has no book for %s", symbol)
459		}
460		view := engine.BookView{
461			Symbol:     symbol,
462			PriceScale: meta.PriceScale,
463			Depth:      100,
464			Bids:       levelsFrom(book.Bids, 100),
465			Asks:       levelsFrom(book.Asks, 100),
466			BidCount:   len(book.Bids),
467			AskCount:   len(book.Asks),
468			OpenOrders: len(book.Index),
469			Crossed:    engine.BookCrossed(book),
470		}
471		if len(book.Bids) > 0 {
472			price := engine.ScalePrice(book.Bids[0].Price, meta.PriceScale)
473			view.BestBid = &price
474		}
475		if len(book.Asks) > 0 {
476			price := engine.ScalePrice(book.Asks[0].Price, meta.PriceScale)
477			view.BestAsk = &price
478		}
479		for i := len(state.Trades) - 1; i >= 0; i-- {
480			if state.Trades[i].Symbol == symbol {
481				price := engine.ScalePrice(state.Trades[i].Price, meta.PriceScale)
482				view.LastTrade = &price
483				break
484			}
485		}
486		return view, nil
487	}
488	
489	func levelsFrom(levels []*engine.LevelState, depth int) []engine.Level {
490		out := []engine.Level{}
491		for i, level := range levels {
492			if i >= depth {
493				break
494			}
495			quantity := int64(0)
496			for _, order := range level.Orders {
497				quantity += order.Remaining
498			}
499			out = append(out, engine.Level{Price: level.Price, Quantity: quantity, OrderCount: len(level.Orders)})
500		}
501		return out
502	}
503	
504	func rebuiltTradePage(state *engine.State, symbol string) (engine.TradePage, error) {
505		meta, ok := state.Symbols[symbol]
506		if !ok {
507			return engine.TradePage{}, fmt.Errorf("rebuilt state has no symbol %s", symbol)
508		}
509		total := 0
510		for i := range state.Trades {
511			if state.Trades[i].Symbol == symbol {
512				total++
513			}
514		}
515		return engine.TradePage{Symbol: symbol, PriceScale: meta.PriceScale, Total: total, Limit: 1000}, nil
516	}
517	
518	func (a *API) idempotencyKey(request *http.Request) (string, error) {
519		return engine.ValidateIdempotencyKey(request.Header.Get("Idempotency-Key"))
520	}
521	
522	func readBody(request *http.Request) ([]byte, error) {
523		if request.Body == nil || request.ContentLength == 0 {
524			return nil, nil
525		}
526		if request.ContentLength > maxBodyBytes {
527			return nil, invalidf("request body must not exceed %d bytes", maxBodyBytes)
528		}
529		mediaType := request.Header.Get("Content-Type")
530		if index := strings.Index(mediaType, ";"); index >= 0 {
531			mediaType = mediaType[:index]
532		}
533		if strings.TrimSpace(strings.ToLower(mediaType)) != "application/json" {
534			return nil, invalidf("Content-Type must be application/json")
535		}
536		raw, err := io.ReadAll(io.LimitReader(request.Body, maxBodyBytes+1))
537		if err != nil {
538			return nil, invalidf("request body could not be read")
539		}
540		if len(raw) > maxBodyBytes {
541			return nil, invalidf("request body must not exceed %d bytes", maxBodyBytes)
542		}
543		return raw, nil
544	}
545	
546	func decodeDocument(raw []byte, target any) error {
547		if len(raw) == 0 {
548			return invalidf("request body must not be empty")
549		}
550		decoder := json.NewDecoder(strings.NewReader(string(raw)))
551		decoder.DisallowUnknownFields()
552		if err := decoder.Decode(target); err != nil {
553			return invalidf("request body must be a valid JSON object: %s", err.Error())
554		}
555		var trailing any
556		if err := decoder.Decode(&trailing); err != io.EOF {
557			return invalidf("request body must contain exactly one JSON object")
558		}
559		return nil
560	}
561	
562	// queryValues rejects unknown or repeated query parameters.
563	func queryValues(rawQuery string, allowed []string) (url.Values, error) {
564		values, err := url.ParseQuery(rawQuery)
565		if err != nil {
566			return nil, invalidf("query string is not valid")
567		}
568		for name, entries := range values {
569			known := false
570			for _, candidate := range allowed {
571				if name == candidate {
572					known = true
573				}
574			}
575			if !known {
576				return nil, invalidf("unknown query parameter %s", name)
577			}
578			if len(entries) != 1 {
579				return nil, invalidf("query parameter %s must appear exactly once", name)
580			}
581		}
582		return values, nil
583	}
584	
585	func (a *API) writeResult(response http.ResponseWriter, result callResult) {
586		if result.err != nil {
587			a.writeError(response, result.err)
588			return
589		}
590		a.writeJSON(response, result.status, result.body)
591	}
592	
593	// callResult is what every routed handler returns.
594	type callResult struct {
595		status int
596		body   any
597		err    error
598	}
599	
600	func (a *API) writeJSON(response http.ResponseWriter, status int, body any) {
601		encoded, err := json.Marshal(body)
602		if err != nil {
603			a.writeError(response, fmt.Errorf("response could not be encoded: %w", err))
604			return
605		}
606		response.Header().Set("Content-Type", "application/json; charset=utf-8")
607		response.WriteHeader(status)
608		if _, err := response.Write(encoded); err != nil {
609			log.Printf("response write failed: %v", err)
610		}
611	}
612	
613	func (a *API) writeError(response http.ResponseWriter, err error) {
614		status := http.StatusInternalServerError
615		code := "internal_error"
616		message := "internal server error"
617		switch {
618		case errors.Is(err, engine.ErrValidation):
619			status, code, message = http.StatusBadRequest, "validation_error", err.Error()
620		case errors.Is(err, engine.ErrNotFound):
621			status, code, message = http.StatusNotFound, "not_found", err.Error()
622		case errors.Is(err, engine.ErrConflict):
623			status, code, message = http.StatusConflict, "conflict", err.Error()
624		default:
625			var typed *apiError
626			if errors.As(err, &typed) {
627				status, code, message = typed.status, typed.code, typed.message
628			}
629		}
630		a.writeJSON(response, status, errorBody{Error: errorDetail{Code: code, Message: message}})
631	}
632	
633	// apiError is a transport level error that is not part of the engine domain.
634	type apiError struct {
635		status  int
636		code    string
637		message string
638	}
639	
640	func (e *apiError) Error() string { return e.message }
641	
642	func invalidf(format string, args ...any) error {
643		return &engine.ValidationError{Message: fmt.Sprintf(format, args...)}
644	}
645	
646	func notFoundf(format string, args ...any) error {
647		return &engine.NotFoundError{Message: fmt.Sprintf(format, args...)}
648	}
649	
650	// Listen binds the configured address and returns the listener so the caller can
651	// print the listening line only once the port is actually held.
652	func Listen(host string, port int) (net.Listener, error) {
653		return net.Listen("tcp", fmt.Sprintf("%s:%d", host, port))
654	}
655	
656	// Serve runs the HTTP server until it fails.
657	func Serve(listener net.Listener, handler http.Handler) error {
658		server := &http.Server{
659			Handler:           handler,
660			ReadHeaderTimeout: 10 * time.Second,
661		}
662		return server.Serve(listener)
663	}
