1	// Command matchbook runs the Matchbook limit order book matching engine and its
2	// deterministic replay API.
3	package main
4	
5	import (
6		"flag"
7		"fmt"
8		"log"
9		"os"
10		"os/signal"
11		"strconv"
12		"strings"
13		"syscall"
14		"time"
15	
16		"matchbook/internal/engine"
17		"matchbook/internal/server"
18	)
19	
20	const productName = "Matchbook"
21	
22	func main() {
23		host := flag.String("host", "127.0.0.1", "interface to bind")
24		port := flag.Int("port", 8080, "TCP port to bind")
25		dataDir := flag.String("data", "data", "directory holding the event log")
26		symbols := flag.String("symbols", "", "comma separated symbol list registered at startup as SYMBOL:SCALE")
27		flag.Parse()
28	
29		matching, err := engine.NewEngine(*dataDir, func() int64 {
30			return time.Now().UnixMilli()
31		})
32		if err != nil {
33			log.Fatalf("matchbook: %v", err)
34		}
35		defer matching.Close()
36	
37		if err := seedSymbols(matching, *symbols); err != nil {
38			log.Fatalf("matchbook: %v", err)
39		}
40	
41		listener, err := server.Listen(*host, *port)
42		if err != nil {
43			log.Fatalf("matchbook: %v", err)
44		}
45		fmt.Printf("%s listening on http://%s:%d\n", productName, *host, *port)
46	
47		shutdown := make(chan os.Signal, 1)
48		signal.Notify(shutdown, os.Interrupt, syscall.SIGTERM)
49	
50		done := make(chan error, 1)
51		go func() {
52			done <- server.Serve(listener, server.New(matching).Handler())
53		}()
54		select {
55		case err := <-done:
56			if err != nil {
57				log.Fatalf("matchbook: %v", err)
58			}
