}

func TestIOCAndFOKHTTPValidation(t *testing.T) {
	handler, _ := newAPI(t)
	createSymbol(t, handler, `{"symbol":"ACME","price_scale":0}`, "")

	cases := []struct {
		name string
		body string
	}{
